SELECT row_to_json(fc) FROM ( SELECT 'FeatureCollection' AS type, array_to_json(array_agg(f)) AS features FROM ( SELECT gid AS id, 'feature' AS type , ST_AsGeoJSON(geom)::json as geometry , ( SELECT row_to_json(t) FROM ( SELECT ${params.cols} ) AS t ) AS properties FROM ${params.layerName} cb
${params.filter}
OFFSET #{params.firstIndex} LIMIT #{params.count} ) AS f ) AS fc

SELECT row_to_json(fc) FROM ( SELECT 'FeatureCollection' AS type, array_to_json(array_agg(f)) AS features FROM ( SELECT gid AS id, 'feature' AS type , ST_AsGeoJSON(geom)::json as geometry , ( SELECT row_to_json(t) FROM ( SELECT ${params.cols} ) AS t ) AS properties FROM ${params.layerName} cb
${params.filter}
OFFSET #{params.firstIndex}
LIMIT #{params.count}
) AS f ) AS fc

      SELECT array_to_string(ARRAY(SELECT 'cb' || '.' || c.column_name
    FROM information_schema.columns As c
        WHERE table_name = #{params.layerName}
        AND  c.column_name NOT IN('geom', 'gid', 'layertype','calarea', 'minx', 'miny', 'maxx', 'maxy', 'gdpdjb2')
), ',') As sqlstmt
